-- 0031: Refresh reviewed public resume content and project descriptions. Prepared locally; do not apply or deploy without review.

UPDATE sections SET zh='{"name":"江嘉元","title":"產品應用 AE・系統整合 SI・FAE","bio":"元智大學電機系學士班在學，預計 2027 年 9 月畢業。從 FRC 機器人、PCB 改版與焊接除錯，到教師委託系統的需求、權限和驗收，我做過硬體、軟體及整合工作；求職方向為產品應用 AE、系統整合 SI 與 FAE。可實習時間為 2027/1/11–2/22 與 2027 年 7–8 月，學期間無法持續到班；英文閱讀中等，聽／說／寫略懂。","avatar":"/455AD532-F2CF-492B-B26C-CEB9053049D5.jpg","contact":{"email":"johnjia9491@gmail.com","location":"台北市, 台灣"},"links":{"github":"Jcsk7049","linkedin":"jiayuan-jiang0901"}}', en='{"name":"Chiang Jia Yuan","title":"Product Applications · Systems Integration · FAE","bio":"I am an Electrical Engineering bachelor’s student at Yuan Ze University, expected to graduate in September 2027. My work spans FRC robots, PCB revision and soldering/debugging, and requirements, permissions, and acceptance for a teacher-commissioned system. I am interested in product applications, systems integration, and FAE roles. I can intern Jan 11–Feb 22, 2027 and July–August 2027; I cannot maintain an in-person schedule during the semester. English reading is intermediate; listening, speaking, and writing are basic.","avatar":"/455AD532-F2CF-492B-B26C-CEB9053049D5.jpg","contact":{"email":"johnjia9491@gmail.com","location":"Taipei, Taiwan"},"links":{"github":"Jcsk7049","linkedin":"jiayuan-jiang0901"}}', updated_at=datetime('now') WHERE key='profile';

UPDATE sections SET zh='[{"school":"元智大學","degree":"電機工程學系｜學士班在學（預計 2027 年 9 月畢業）","period":"2024.09 – 2027.09"},{"school":"南港高工","degree":"電子科","period":"2020.09 – 2023.06"}]', en='[{"school":"Yuan Ze University","degree":"B.S. Electrical Engineering | In progress, expected Sep 2027","period":"2024.09 – 2027.09"},{"school":"Nangang Vocational H.S.","degree":"Electronics Program","period":"2020.09 – 2023.06"}]', updated_at=datetime('now') WHERE key='education';

UPDATE sections SET zh='[{"role":"研究專題生","organization":"元智大學 林書彥教授實驗室","period":"2025.05 – 現在","description":"參與 ICU VAP 早期預警研究，負責資料整理、模型比較與驗證稽核。論文接受後，我重新核對資料索引、時間對齊與病人層切分；修正後 AUROC 約 0.61。這是單中心資料的模型評估結果，不代表臨床預測效能。論文以第一作者獲 IEEE GCCE 2026 poster 接受，預定 2026 年 10 月 29 日報告。"},{"role":"FRC 團隊顧問（非正式聘僱）","organization":"FRC TEAM 7645","period":"2023 – 現在","description":"以團隊顧問身份參與，非正式聘僱。參與 FRC 機器人系統整合；我實際操作的範圍包括 Inventor 機構建模、CNC 加工，以及 LabVIEW 運動學與 PID 調校。近期以 LLM 輔助檢視韌體除錯步驟，和隊員一起依錯誤訊息追查問題。"},{"role":"競賽選手","organization":"南港高工 NK-MTC 7645","period":"2020.06 – 2023.09","description":"代表南港高工參與 FRC 與全國技能競賽。三人集體創作機器人專案中，我負責 24V 配電、繼電器 H 橋與全車配線；機構加工和控制程式由隊友負責。FRC 團隊成果另列於專案與獲獎紀錄。"}]', en='[{"role":"Research Project Student","organization":"Yuan Ze Univ. — Prof. Lin Shu-Yan''s Lab","period":"2025.05 – Present","description":"I handled data preparation, model comparisons, and evaluation audits for an ICU VAP early-warning study. After acceptance, I rechecked data indexing, time alignment, and patient-level splits; the corrected AUROC is about 0.61. This is a model-evaluation result on single-center data, not evidence of clinical performance. The first-author paper was accepted as an IEEE GCCE 2026 poster, scheduled for October 29, 2026."},{"role":"FRC Team Advisor (Non-employee)","organization":"FRC TEAM 7645","period":"2023 – Present","description":"I contribute as a team advisor, not as an employee. My hands-on work in FRC robot integration includes Inventor mechanical modeling, CNC machining, and LabVIEW kinematics and PID tuning. More recently, I have used an LLM to help review firmware-debugging steps and worked with students to trace issues from error messages.","frc":true},{"role":"Competitive Athlete","organization":"Nangang VHS NK-MTC 7645","period":"2020.06 – 2023.09","description":"Represented Nangang Vocational High School in FRC and National Skills Competition events. On the three-person team robot, I handled 24V power distribution, the relay H-bridge, and vehicle wiring; teammates handled mechanical fabrication and control software. FRC team results are listed separately in the project and awards sections."}]', updated_at=datetime('now') WHERE key='experience';

UPDATE sections SET zh='{"data_analysis":{"title":"數據分析","en":"Data Analysis","overview":"做過臨床資料整理、特徵處理與模型比較；在 VAP 論文接受後也重新稽核索引、時間對齊和驗證切分。","skills":[{"name":"深度學習","level":"熟悉","desc":"以 TensorFlow／Keras 建立及比較 LSTM 時序模型，並重跑病人層驗證。單中心資料修正後 AUROC 約 0.61，不能據此主張臨床預測效能。","projects":["VAP 深度學習預測系統"]},{"name":"LightGBM","level":"熟悉","desc":"在 BitOGuard 團隊專案中與 XGBoost 組成加權模型，並用 SHAP 檢視特徵貢獻；結果依競賽資料與評估設定解讀。","projects":["AWS x BitoPro 黑客松"]},{"name":"XGBoost","level":"熟悉","desc":"在 BitOGuard 團隊專案中與 LightGBM 組成加權模型；另用於課程中的訊號分類。","projects":["AWS x BitoPro 黑客松"]},{"name":"特徵工程","level":"熟悉","desc":"曾整理時域、頻域特徵及臨床時間序列資料；VAP 專案後續也檢查資料索引和時間對齊。","projects":["VAP 深度學習預測系統","AWS x BitoPro 黑客松"]},{"name":"訊號過濾","level":"熟悉","desc":"在訊號課程與研究資料前處理中做過濾波、標準化和缺值處理；依資料來源檢查處理結果。","projects":["VAP 深度學習預測系統"]},{"name":"數據結構化","level":"熟悉","desc":"使用 Python／pandas 整理臨床資料並建構分析欄位；VAP 稽核中修正時間對齊與欄位問題。","projects":["VAP 深度學習預測系統","AWS x BitoPro 黑客松"]}]},"programming":{"title":"程式開發","en":"Programming","overview":"以 C／C++ 接觸嵌入式韌體，以 Python 整理資料和模型比較；也用 LabVIEW 完成過 FRC 運動控制。","skills":[{"name":"C / C++","level":"基礎","desc":"具備 C／C++ 基礎；在 QMK／STM32 專案調整 ChibiOS HAL 設定並排查編譯問題，尚不宣稱熟練底層驅動或暫存器開發。","projects":["FRC Swerve Drive 全向輪控制系統","QMK x STM32 客製鍵盤"]},{"name":"Python","level":"熟悉","desc":"用於資料整理、模型比較與課程作業；部分網站和工具由 LLM 協助實作，我負責需求拆解、整合和實際檢查。","projects":["VAP 深度學習預測系統","AWS x BitoPro 黑客松"]},{"name":"LabVIEW","level":"熟悉","desc":"在 FRC Swerve 專案實作運動學與 PID 控制；控制創新獎是團隊競賽成果。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"Arduino","level":"熟悉","desc":"在 ESP32 無線打地鼠教具中處理 ESP-NOW 通訊與繼電器控制，並配合實體除錯。","projects":["ESP32 無線打地鼠機"]},{"name":"MATLAB","level":"基礎","desc":"拿來做訊號處理分析跟演算法驗證，寫程式前先用它把濾波效果、模型邏輯畫出來確認一遍。","projects":[]}]},"eda":{"title":"電路設計與量測","en":"Electronic Design Automation","overview":"做過開源 PCB 改版、焊接與實驗電路量測；Altium 曾使用，目前需要複習。","skills":[{"name":"Altium Designer","level":"基礎","desc":"高職時使用 Altium 完成過電路板設計；目前需要複習，不主張高速多層板設計經驗。","projects":[]},{"name":"EasyEDA Pro（立創EDA）","level":"熟悉","desc":"用於 QMK／STM32 數字鍵盤開源 PCB 改版，整理電路與板圖並輸出製作資料；本人另完成焊接、燒錄和功能檢查。","projects":["QMK x STM32 數字鍵盤"]},{"name":"KiCAD","level":"基礎","desc":"接觸 KiCad 電路圖與 PCB 工具；網站專案內容以實際做過的板子為準，不把工具接觸等同於熟練。","projects":[]},{"name":"OrCAD","level":"基礎","desc":"用於電路圖與基礎模擬課程；不把接觸經驗描述為完整量產設計能力。","projects":[]},{"name":"BJT 音訊放大器除錯","level":"熟悉","desc":"在大二電子電路實驗中完成兩級 BJT 音訊放大器 PCB；經兩次重做，排除殘銅短路與元件腳位鏡像問題，最後以 8Ω 喇叭確認可播放。","projects":["類比電路實作：音訊放大器 PCB 設計"]},{"name":"RC／RL 示波器量測","level":"基礎","desc":"在電子電路實驗中使用示波器觀察 RC／RL 電路響應並記錄量測結果。","projects":["大二下電子電路實驗"]}]},"manufacturing":{"title":"機構加工","en":"Manufacturing","overview":"參與機構設計與實體加工；Inventor 用於 FRC 機構建模，CNC、線切割和 3D 列印經驗來自團隊專案。","skills":[{"name":"CNC 銑床","level":"基礎","desc":"在 FRC 團隊專案參與 CNC 銑床加工；本人工作範圍依各代專案分工。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"Mastercam","level":"基礎","desc":"在 FRC 機器人零件製作中接觸 Mastercam 刀具路徑；不將團隊整體製程描述為個人獨立完成。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"3D 列印","level":"基礎","desc":"在機器人專案接觸 FDM 零件製作與機構配合；描述限於實際參與的零件。","projects":["FRC Swerve Drive 全向輪控制系統","ESP32 無線打地鼠機"]},{"name":"Autodesk Inventor","level":"熟悉","desc":"用於 FRC 機構建模；各代底盤由多人共同設計與製作。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"AutoCAD","level":"基礎","desc":"接觸 AutoCAD 二維圖面與尺寸標註；不主張熟悉完整加工圖面公差流程。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"Fusion 360","level":"基礎","desc":"快速建概念模型，CAM 整合也在裡面，初期設計想法用它試很方便，直接從 3D 模型生成加工路徑，小批量自己做。","projects":[]},{"name":"金屬焊接","level":"基礎","desc":"在團隊製作中接觸金屬結構件處理；加工工作依團隊分工完成。","projects":["FRC Swerve Drive 全向輪控制系統"]},{"name":"雷射切割","level":"基礎","desc":"在團隊製作中接觸板材與零件切割，經驗以實際參與的作品為準。","projects":[]},{"name":"基礎機械加工","level":"基礎","desc":"接觸手動加工設備與量具操作，經驗以高職課程及機器人製作為主。","projects":[]}]},"vibecoding":{"title":"Vibe Coding 設計","en":"Vibe Coding & Product Delivery","overview":"把需求寫成流程、欄位和驗收條件，再與 LLM 協作實作；我負責方向、整合和回到實際環境檢查。","skills":[{"name":"LLM 協作開發","level":"熟悉","desc":"先整理目標、限制和驗收條件，再用 LLM 協助程式與測試實作；我檢查結果是否符合需求，並用於教師委託樹木系統及個人 Agent 原型。","projects":["FRC 7645 — 官網與後台 CMS","Job Radar — 個人化求職雷達","跨專案 AI Agent 原型","教師委託：校園樹木量測系統"]},{"name":"需求拆解與垂直切片","level":"熟悉","desc":"在校園樹木量測系統中整理學生、教師流程與角色權限，再拆成可逐段驗收的功能。","projects":["南港高工校園樹木量測 PWA","Job Radar — 個人化求職雷達","TeamMatch — 黑客松找隊友平台"]},{"name":"前後端與服務整合","level":"熟悉","desc":"教師委託系統使用 Google Apps Script、Google Sheets 與 PWA；跨專案 Agent 串接 LLM API 和共用紀錄。各專案使用狀態分別註明。","projects":["Job Radar — 個人化求職雷達","南港高工校園樹木量測 PWA","TeamMatch — 黑客松找隊友平台","Analog IC Studio — 類比 IC 自動調參平台","跨專案 AI Agent 原型"]},{"name":"迭代除錯與瀏覽器驗證","level":"熟悉","desc":"為樹木系統準備自動化測試、GitHub Actions CI 與交接文件；教師目前測試使用，尚未正式採用。","projects":["Analog IC Studio — 類比 IC 自動調參平台","Virtual Office — 桌面像素辦公室","南港高工校園樹木量測 PWA"]},{"name":"自動化部署與資料同步","level":"基礎","desc":"使用 Git、GitHub PR 與 GitHub Actions CI 管理和檢查專案；個人 Agent 仍在個人測試，沒有企業部署經驗。","projects":["Job Radar — 個人化求職雷達","南港高工校園樹木量測 PWA","FRC 7645 — 官網與後台 CMS"]}]}}', en='{"data_analysis":{"title":"Data Analysis","en":"Data Analysis","overview":"I have prepared clinical data, built features, and compared models. After paper acceptance, I also audited indexing, time alignment, and evaluation splits.","skills":[{"name":"Deep Learning","level":"熟悉","desc":"Built and compared LSTM time-series models with TensorFlow/Keras and reran patient-level evaluation. The corrected AUROC is about 0.61 on single-center data; this does not establish clinical prediction performance.","projects":["ICU VAP Early-Warning System"]},{"name":"LightGBM","level":"熟悉","desc":"Used with XGBoost in a BitOGuard team project and applied SHAP to inspect feature contributions; results depend on the competition data and evaluation setup.","projects":["AWS × BitoPro Hackathon"]},{"name":"XGBoost","level":"熟悉","desc":"Combined with LightGBM in the BitOGuard team project; also used for signal-classification coursework.","projects":["AWS × BitoPro Hackathon"]},{"name":"Feature Engineering","level":"熟悉","desc":"Prepared time- and frequency-domain features and clinical time-series fields; later audited indexing and time alignment in the VAP study.","projects":["ICU VAP Early-Warning System","AWS × BitoPro Hackathon"]},{"name":"Signal Filtering","level":"熟悉","desc":"Applied filtering, normalization, and missing-value handling in coursework and research preprocessing, checking results against each data source.","projects":["ICU VAP Early-Warning System"]},{"name":"Data Structuring","level":"熟悉","desc":"Used Python and pandas to prepare clinical data and analysis fields. The VAP audit corrected time-alignment and field issues.","projects":["ICU VAP Early-Warning System","AWS × BitoPro Hackathon"]}]},"programming":{"title":"Programming","en":"Programming","overview":"I use C/C++ for embedded work and Python for data preparation and model comparisons. I have also implemented FRC motion control in LabVIEW.","skills":[{"name":"C / C++","level":"基礎","desc":"Basic C/C++ experience. In the QMK/STM32 project, I adjusted ChibiOS HAL settings and investigated build errors; I do not claim advanced low-level driver or register development.","projects":["FRC Swerve Drive Research","QMK × STM32 Custom Numpad"]},{"name":"Python","level":"熟悉","desc":"Used for data preparation, model comparison, and coursework. Some website and tool implementation was assisted by an LLM; I handled requirements, integration, and hands-on checks.","projects":["ICU VAP Early-Warning System","AWS × BitoPro Hackathon"]},{"name":"LabVIEW","level":"熟悉","desc":"Implemented kinematics and PID control in the FRC Swerve project. The Control Innovation Award was a team result.","projects":["FRC Swerve Drive Research"]},{"name":"Arduino","level":"熟悉","desc":"Worked with ESP-NOW communication and relay control on an ESP32 wireless teaching aid, including physical debugging.","projects":["Wireless Whack-a-Mole"]},{"name":"MATLAB","level":"基礎","desc":"Used for signal processing analysis and quick algorithm checks — plotting things out to sanity-check filter behavior and model logic before writing the real implementation.","projects":[]}]},"eda":{"title":"Circuit Design & Measurement","en":"Electronic Design Automation","overview":"I have revised an open-source PCB, soldered and debugged circuits, and measured lab circuits. I have used Altium before and need a refresher.","skills":[{"name":"Altium Designer","level":"基礎","desc":"Used Altium to complete a PCB in vocational high school. I need a refresher and do not claim high-speed multilayer board experience.","projects":[]},{"name":"EasyEDA Pro (LCEDA)","level":"熟悉","desc":"Used to revise the open-source QMK/STM32 numpad PCB and prepare board files; I also soldered, flashed, and function-checked the assembled board.","projects":["QMK × STM32 Custom Numpad"]},{"name":"KiCAD","level":"基礎","desc":"Have used KiCad schematic and PCB tools; tool exposure is not presented as proficiency.","projects":[]},{"name":"OrCAD","level":"基礎","desc":"Used for schematic and basic simulation coursework; this is not a claim of full production-design experience.","projects":[]},{"name":"BJT Audio Amplifier Debugging","level":"熟悉","desc":"Built a two-stage BJT audio-amplifier PCB for a sophomore lab. After two rebuilds, I fixed a copper short and mirrored component footprints; an 8Ω speaker played audio.","projects":["Analog Circuit Lab: Audio Amplifier PCB"]},{"name":"RC/RL Oscilloscope Measurements","level":"基礎","desc":"Used an oscilloscope to observe and record RC/RL circuit responses in electronics laboratory work.","projects":["Sophomore Spring Electronics Circuit Lab"]}]},"manufacturing":{"title":"Manufacturing","en":"Manufacturing","overview":"I have contributed to mechanical design and physical fabrication. Inventor modeling, CNC, wire EDM, and 3D printing experience comes from team projects.","skills":[{"name":"CNC Milling","level":"基礎","desc":"Participated in CNC milling on an FRC team project, machining mechanical parts from drawings. My role varied by chassis generation.","projects":["FRC Swerve Drive Research"]},{"name":"Mastercam","level":"基礎","desc":"Used Mastercam for toolpaths on FRC robot parts. I do not present the team’s full fabrication workflow as work completed independently.","projects":["FRC Swerve Drive Research"]},{"name":"3D Printing","level":"基礎","desc":"Worked with FDM parts and mechanical fit on robot projects; descriptions are limited to parts I handled.","projects":["FRC Swerve Drive Research","Wireless Whack-a-Mole"]},{"name":"Autodesk Inventor","level":"熟悉","desc":"Used for FRC mechanical modeling; multiple team members designed and built each chassis generation.","projects":["FRC Swerve Drive Research"]},{"name":"AutoCAD","level":"基礎","desc":"Have used AutoCAD for 2D drawings and dimensions; I do not claim proficiency in complete machining drawing tolerances.","projects":["FRC Swerve Drive Research"]},{"name":"Fusion 360","level":"基礎","desc":"Quick concept modeling with built-in CAM — good for early design exploration, and you can go straight from the 3D model to a machining path for small-batch parts.","projects":[]},{"name":"Metal Welding","level":"基礎","desc":"Worked with metal structures in team builds; fabrication tasks were shared according to team roles.","projects":["FRC Swerve Drive Research"]},{"name":"Laser Cutting","level":"基礎","desc":"Have used sheet and part cutting in team builds; experience is limited to work I handled.","projects":[]},{"name":"Basic Machining","level":"基礎","desc":"Basic exposure to manual machining equipment and measuring tools through vocational coursework and robot builds.","projects":[]}]},"vibecoding":{"title":"Vibe Coding & Product Delivery","en":"Vibe Coding & Product Delivery","overview":"I turn requirements into flows, fields, and acceptance criteria, then work with an LLM on implementation. I own the direction, integration, and hands-on review.","skills":[{"name":"LLM-assisted coding","level":"熟悉","desc":"I define the goal, constraints, and acceptance criteria before asking an LLM to help with implementation and tests. I check the result against requirements on the teacher-commissioned tree system and personal Agent prototype.","projects":["FRC 7645 — Website & Admin CMS","Job Radar: Personalized Job Search Dashboard","Cross-Project AI Agent Prototype","Teacher-Commissioned Campus Tree Measurement System"]},{"name":"Requirement slicing","level":"熟悉","desc":"For the campus tree system, I defined student/teacher flows and role permissions, then split them into features that could be accepted one at a time.","projects":["NKHS Campus Tree Measurement PWA","Job Radar: Personalized Job Search Dashboard","TeamMatch — Hackathon Teammate Finder"]},{"name":"Full-stack integration","level":"熟悉","desc":"The teacher-commissioned system uses Google Apps Script, Sheets, and a PWA; the cross-project Agent connects an LLM API with shared records. Each project’s usage status is stated separately.","projects":["Job Radar: Personalized Job Search Dashboard","NKHS Campus Tree Measurement PWA","TeamMatch — Hackathon Teammate Finder","Analog IC Studio — Automated Analog IC Tuning Platform","Cross-Project AI Agent Prototype"]},{"name":"Iterative debugging & browser review","level":"熟悉","desc":"Prepared automated tests, GitHub Actions CI, and handover docs for the tree system. Teachers are testing it; it has not been formally adopted.","projects":["Analog IC Studio — Automated Analog IC Tuning Platform","Virtual Office — Desktop Pixel Workspace","NKHS Campus Tree Measurement PWA"]},{"name":"Deployment & data sync","level":"基礎","desc":"Used Git, GitHub PRs, and GitHub Actions CI to manage and check project work. The personal Agent is still in personal testing; I have no enterprise deployment experience.","projects":["Job Radar: Personalized Job Search Dashboard","NKHS Campus Tree Measurement PWA","FRC 7645 — Website & Admin CMS"]}]}}', updated_at=datetime('now') WHERE key='skills_detail';

UPDATE projects SET zh='{"id":"vap","featured":true,"cover":"/images/vap/cover-ai.jpg","category":"大學專題作品","title":"ICU VAP 早期預測：試驗性方法論驗證研究","period":"2025 – 現在","description":"亞東紀念醫院單中心 ICU 研究。論文接受後，我重新稽核資料索引、時間對齊和病人層切分；修正後 AUROC 約 0.61，不能視為臨床預測效能。論文為第一作者，獲 IEEE GCCE 2026 poster 接受，預定 2026 年 10 月 29 日報告。","badge":"IEEE GCCE 2026 · Poster","tags":["LSTM · Time-Series","Integrated Gradients","Stay-Level CV","SMOTE","Medical AI"],"detail":{"images":[{"src":"/images/vap/fig-pipeline.png","caption":"系統流程：特徵篩選 → 滑動視窗 → LSTM → 多時程評估"},{"src":"/images/vap/fig-lstm-vs-baseline.png","caption":"原論文視窗層基準比較；同一病人跨訓練/測試集，複查後不作效能主張"},{"src":"/images/vap/fig-lstm-performance.png","caption":"原論文視窗層結果圖；評估設定複查後，數字不代表病人層泛化效能"}],"purpose":"研究原本想評估 ICU 時序資料能否預測 VAP。投稿後的複查發現資料處理和評估條件有問題，於是把重點轉為檢查這些條件如何影響模型結果。","concept":"我重新核對病人、時間窗與標籤的對應，也檢查同一病人是否同時出現在訓練與測試資料。分析還發現呼吸器廠牌和收案年份與標籤有關，現有資料無法排除來源差異的影響。","outcome":"論文接受後，我持續修正資料索引、時間對齊及病人層切分；修正後 AUROC 約 0.61。這項單中心分析目前呈現的是資料與評估流程的限制，不能當成臨床效能。第一作者論文獲 IEEE GCCE 2026 poster 接受，預定 2026 年 10 月 29 日報告。","tech":[{"group":"深度學習","items":[{"name":"LSTM 時序建模","desc":"以 TensorFlow / Keras 建立三層 LSTM 時序分類模型，並比較不同窗口與簡化模型；在小型單中心資料上的結果需要配合同病人切分與來源分層解讀。"},{"name":"類別不平衡處理","desc":"在訓練折內使用 SMOTE，避免合成樣本跨越訓練與測試邊界。後續比較未能證明 GAN 或其他擴增方式優於不擴增或 SMOTE。"},{"name":"可解釋 AI（XAI）","desc":"以 Integrated Gradients 歸因各特徵對每筆預測的貢獻，進而設計 Ablation Study 驗證 Top 4 特徵的不可取代性"}]},{"group":"實驗設計","items":[{"name":"防洩漏驗證設計","desc":"以病人為單位切分資料，檢查同一病人是否跨越訓練與測試集。MIMIC-IV 復刻與亞東資料的分析屬不同實驗；目前不以其結果主張臨床預測效能。"},{"name":"Per-fold 正規化","desc":"在交叉驗證各折內計算正規化統計量，避免測試折統計量進入訓練流程。"},{"name":"Ablation Study","desc":"曾在視窗層設定下移除 mv_total（mv≡Vt×RR），觀察到 AUROC 與 AUPRC 上升；此分析未在修正後的病人層設定重跑，不作為目前結論。"}]},{"group":"特徵工程","items":[{"name":"滑動視窗建構","desc":"將 ICU 時序資料轉成固定長度窗口，並依預測時間點建立輸入資料；窗口切分須以病人為群組，避免同一病人跨折。"},{"name":"生理訊號前處理","desc":"使用 pandas / NumPy 整理多來源生命徵象與呼吸器資料；稽核中修正時間對齊與欄位覆寫問題，顯示前處理需逐來源核對。"}]}],"github":""}}', en='{"id":"vap","featured":true,"cover":"/images/vap/cover-ai.jpg","category":"大學專題作品","title":"ICU VAP Prediction: Pilot Methodology Validation","period":"2025 – Present","description":"A single-center ICU study at Far Eastern Memorial Hospital. After acceptance, I audited data indexing, time alignment, and patient-level splits; the corrected AUROC is about 0.61 and is not evidence of clinical prediction performance. First-author paper accepted as an IEEE GCCE 2026 poster, scheduled for October 29, 2026.","badge":"IEEE GCCE 2026 · Poster","tags":["LSTM · Time-Series","Integrated Gradients","Stay-Level CV","SMOTE","Medical AI"],"detail":{"images":[{"src":"/images/vap/fig-pipeline.png","caption":"Pipeline: feature selection → sliding window → LSTM → multi-horizon evaluation"},{"src":"/images/vap/fig-lstm-vs-baseline.png","caption":"Original window-level baseline comparison; patients crossed the train/test split, so these are not performance claims"},{"src":"/images/vap/fig-lstm-performance.png","caption":"Original window-level result plot; the audited setup does not establish patient-level generalization"}],"purpose":"The study began by asking whether ICU time series could predict VAP. A post-submission audit found issues in data processing and evaluation, so I examined how those conditions affected the results.","concept":"I checked patient, time-window, and label alignment, and whether the same patient appeared in both training and test data. Ventilator brand and enrollment year were also associated with labels, so source effects cannot be ruled out.","outcome":"After acceptance, I continued correcting data indexing, time alignment, and patient-level splits; the corrected AUROC is about 0.61. This single-center analysis documents limitations in the data and evaluation pipeline, not clinical performance. The first-author paper was accepted as an IEEE GCCE 2026 poster, scheduled for October 29, 2026.","tech":[{"group":"Deep Learning","items":[{"name":"LSTM Time-Series Modeling","desc":"Built a three-layer TensorFlow/Keras LSTM classifier and compared window lengths and smaller models. Results on this small single-center cohort require patient-level splitting and source-stratified interpretation."},{"name":"Class Imbalance Handling","desc":"Applied SMOTE within each training fold to keep synthetic samples out of test folds. Later experiments did not establish that GAN or other augmentation methods outperform no augmentation or SMOTE."},{"name":"Explainable AI (XAI)","desc":"Integrated Gradients was used to inspect feature contributions. Feature selection and attribution rankings were affected by full-dataset selection and data-processing issues, so the Top 4 ranking is not treated as stable."}]},{"group":"Experimental Design","items":[{"name":"Leakage-Free Validation","desc":"Used patient-level splits to check whether one patient crossed the training and test sets. The MIMIC-IV replication and FEMH analysis are separate experiments; neither is used here to claim clinical prediction performance."},{"name":"Per-fold Normalization","desc":"Computed normalization statistics independently inside each cross-validation fold to keep test-fold statistics out of training."},{"name":"Ablation Study","desc":"Removing mv_total (mv≡Vt×RR) improved AUROC and AUPRC under the window-level setup. This analysis was not rerun with the corrected patient-level evaluation and is not a current conclusion."}]},{"group":"Feature Engineering","items":[{"name":"Sliding Window Construction","desc":"Converted ICU time series into fixed-length windows for each prediction horizon. Splits must group by patient so windows from one patient cannot cross folds."},{"name":"Physiological Signal Preprocessing","desc":"Used pandas and NumPy to prepare multi-source vital-sign and ventilator data. The audit corrected time-alignment and field-overwrite issues, showing why each source needs explicit checks."}]}],"github":""}}', updated_at=datetime('now') WHERE id='vap';

UPDATE projects SET zh='{"id":"qmk-stm32-keyboard","cover":"/images/qmk-stm32-keyboard/numpad-hero.jpg","category":"大學校外作品","title":"開源硬體整合：QMK x STM32 數字鍵盤","period":"2026","description":"以開源 PCB 設計為基礎改版，完成焊接、燒錄與基本功能驗證；調整 QMK／ChibiOS HAL 設定並排查編譯問題。","tags":["STM32F103","QMK","ChibiOS HAL","開源 PCB 改版","焊接與功能驗證"],"detail":{"images":[{"src":"/images/qmk-stm32-keyboard/numpad-top.jpg","caption":"完成品俯視"},{"src":"/images/qmk-stm32-keyboard/numpad-hero.jpg","caption":"與主鍵盤並用"}],"purpose":"把 QMK 韌體設定到 STM32 數字鍵盤上，並完成實體板子的改版與功能確認。","concept":"沿用開源 PCB 設計再做修改；依照 QMK 專案現有結構調整 ChibiOS HAL 設定，透過重新編譯與錯誤訊息排查設定問題。","outcome":"完成開源 PCB 改版、焊接、韌體燒錄與基本功能驗證。","tech":[{"group":"韌體設定與驗證","items":[{"name":"QMK／ChibiOS HAL 設定","desc":"依現有 QMK／ChibiOS 專案調整設定，根據編譯錯誤逐步檢查。"},{"name":"STM32 韌體燒錄與功能驗證","desc":"完成 STM32F103 燒錄，並以基本按鍵輸入檢查實體鍵盤功能。"}]},{"group":"PCB 實作","items":[{"name":"開源 PCB 改版","desc":"以既有開源板為基礎修改，沒有從零設計 PCB。"},{"name":"焊接與組裝","desc":"完成元件焊接、組裝及上電後的基本檢查。"}]}],"github":"https://github.com/Jcsk7049/qmk-stm32-keyboard","video":"UQ_tA-CO8Yw"}}', en='{"id":"qmk-stm32-keyboard","cover":"/images/qmk-stm32-keyboard/numpad-hero.jpg","category":"大學校外作品","title":"Open-Source Hardware Integration: QMK × STM32 Numpad","period":"2026","description":"Revised an open-source PCB design, soldered and flashed an STM32F103, and checked basic keyboard functions. I adjusted existing QMK/ChibiOS HAL settings and investigated build issues.","tags":["STM32F103","QMK","ChibiOS HAL","Open-source PCB revision","Soldering and validation"],"detail":{"images":[{"src":"/images/qmk-stm32-keyboard/numpad-top.jpg","caption":"Completed numpad — top view"},{"src":"/images/qmk-stm32-keyboard/numpad-hero.jpg","caption":"In use alongside main keyboard"}],"purpose":"Configure QMK firmware for an STM32 numpad, revise the physical board, and verify basic functions.","concept":"I modified an existing open-source PCB design and adjusted settings within the existing QMK/ChibiOS project, using build errors to trace configuration issues.","outcome":"Completed the open-source PCB revision, soldering, firmware flashing, and basic functional checks.","tech":[{"group":"Firmware Setup and Validation","items":[{"name":"QMK/ChibiOS HAL Settings","desc":"Adjusted settings in the existing QMK/ChibiOS project and checked build errors iteratively."},{"name":"STM32 Flashing and Functional Check","desc":"Flashed the STM32F103 and checked basic key input on the physical numpad."}]},{"group":"PCB Implementation","items":[{"name":"Open-Source PCB Revision","desc":"Modified an existing open-source board; the PCB was not designed from scratch."},{"name":"Soldering and Assembly","desc":"Soldered and assembled the board, then performed basic power-on checks."}]}],"github":"https://github.com/Jcsk7049/qmk-stm32-keyboard","video":"UQ_tA-CO8Yw"}}', updated_at=datetime('now') WHERE id='qmk-stm32-keyboard';

UPDATE projects SET zh='{"id":"swerve","cover":"/images/swerve/swerve-assembled-side.jpg","category":"高職選手作品","title":"Swerve Drive 全向輪控制研究","period":"2020 – 2023","frc":true,"description":"參與 FRC Swerve 底盤三代迭代；本人實作範圍包括 Inventor 建模、CNC 加工，以及 LabVIEW 運動學與 PID 調整。2022 年獲獎為團隊競賽成果。","tags":["LabVIEW","PID Control","CNC 加工","線切割","Robotics","3D 列印"],"detail":{"purpose":"FRC 團隊逐代修改 Swerve 底盤。我參與其中部分建模、加工與控制工作；每代設計與製作由隊員共同完成。","concept":"本人實作範圍包含 Inventor 機構建模、CNC 加工，以及以 LabVIEW 編寫運動學並調整 PID。其他機構、配線與組裝工作依團隊分工完成。","outcome":"2022 年 FRC 台灣鴻海區域賽獲控制創新獎，為團隊成果；2020 年獲獎亦屬團隊紀錄。此頁只列出本人實際參與的工作範圍。","tech":[{"group":"控制系統","items":[{"name":"向量合成運動學","desc":"以向量 X∠θ 分解平移、迴旋、弧形三種運動模式並疊加，取最大力道輪正規化輸出防馬達飽和；以 LabVIEW 圖形化實作完整演算法"},{"name":"PID 閉迴路控制","desc":"各輪獨立編碼器回饋，PID 控制轉向角度，掌握積分飽和（wind-up）與微分濾波在競賽高動態環境下的調參與穩定性取捨"}]},{"group":"機構設計","items":[{"name":"模組化傳動架構","desc":"驅動與轉向馬達孔位共用、齒輪區可換齒調整減速比，不修改鋁板即可適配不同馬達規格；三代迭代中實際驗證模組化對維修速度的提升"},{"name":"輕量化結構設計","desc":"以材料替換策略降重：內部傳動齒輪改 FDM 列印，保留馬達軸金屬件；鋁板 CNC 偷料在保持結構強度前提下減少板材用量"}]},{"group":"精密加工","items":[{"name":"CNC 數值銑削","desc":"加工傳動心軸（六角柱 & 方槽截面），以 4 爪夾盤定位，兩面分次銑削確保截面對稱；相較手工銑床大幅提升尺寸精度與批量重現性"},{"name":"數值線切割","desc":"完成 M1.25–M1.5 正齒輪與直齒斜齒輪的外形與內孔切割，掌握壓板固定、尋邊校正 XY 誤差、路徑模擬確認的完整作業流程"}]}],"github":"","images":[{"src":"/images/swerve/swerve-cad-iso.jpg","caption":"第三代 Swerve Drive — 3D CAD 等角視圖"},{"src":"/images/swerve/swerve-cad-4view.jpg","caption":"第三代 Swerve Drive — 四視圖工程圖"},{"src":"/images/swerve/swerve-assembled-top.jpg","caption":"組裝完成 — 俯視（可見齒輪傳動系統）"},{"src":"/images/swerve/swerve-assembled-side.jpg","caption":"組裝完成 — 側視（馬達與底盤結構）"},{"src":"/images/swerve/swerve-gears-internal.jpg","caption":"內部齒輪組（3D 列印齒輪 + 金屬件）"},{"src":"/images/swerve/swerve-bevel-gear.jpg","caption":"直齒斜齒輪與驅動馬達 CAD 模型"},{"src":"/images/swerve/swerve-plate-cnc.jpg","caption":"CNC 加工完成的鋁板"},{"src":"/images/swerve/swerve-gear-drill.jpg","caption":"金屬斜齒輪鑽孔加工"},{"src":"/images/swerve/swerve-wire-cut-action.jpg","caption":"線切割加工齒輪內孔（進行中）"},{"src":"/images/swerve/swerve-wire-cut-panel.jpg","caption":"線切割機控制面板 — 六角形路徑模擬"},{"src":"/images/swerve/swerve-flowchart-algo.png","caption":"LabVIEW 向量合成運動學演算法流程圖"},{"src":"/images/swerve/swerve-wiring.png","caption":"FRC 機器人電路系統配線圖"}]}}', en='{"id":"swerve","cover":"/images/swerve/swerve-assembled-side.jpg","category":"高職選手作品","title":"Swerve Drive Omnidirectional Research","period":"2020 – 2023","frc":true,"description":"Contributed across three FRC swerve-drive generations. My hands-on work included Inventor modeling, CNC machining, and LabVIEW kinematics and PID tuning. The 2022 award was a team competition result.","tags":["LabVIEW","PID Control","CNC Machining","Wire EDM","Robotics","3D Printing"],"detail":{"purpose":"The FRC team revised its swerve chassis across generations. I contributed to some modeling, fabrication, and control work; each version was designed and built by multiple team members.","concept":"My work included Inventor mechanical modeling, CNC machining, and implementing kinematics and tuning PID in LabVIEW. Other mechanical, wiring, and assembly tasks were completed across the team.","outcome":"The team received the 2022 FRC Taiwan Foxconn Regional Innovation in Control Award; the 2020 award is also a team result. This page identifies my own areas of contribution.","tech":[{"group":"Control System","items":[{"name":"Vector-Composition Kinematics","desc":"Decomposing translation, rotation, and arc motion modes as X∠θ vectors and superimposing them; normalizing by max-force wheel to prevent motor saturation; fully implemented in LabVIEW graphical programming"},{"name":"PID Closed-Loop Control","desc":"Per-wheel independent encoder feedback for PID steering angle control; mastering integral windup and derivative filtering tuning in high-dynamic competition environments"}]},{"group":"Mechanical Design","items":[{"name":"Modular Transmission Architecture","desc":"Drive and steering motor holes shared; gear zone swappable for reduction ratio adjustment without modifying aluminum plates; three-generation iteration validated modular design''s improvement in repair speed"},{"name":"Lightweight Structural Design","desc":"Material substitution for weight reduction: internal gears switched to FDM printing, retaining metal motor shaft gears; CNC material removal from aluminum plates while maintaining structural strength"}]},{"group":"Precision Machining","items":[{"name":"CNC Numerical Milling","desc":"Machining transmission shafts (hex & square cross-sections) with 4-jaw chuck positioning; bilateral milling for cross-sectional symmetry; significantly improved dimensional accuracy and batch reproducibility over manual milling"},{"name":"Wire EDM","desc":"M1.25–M1.5 spur and bevel gear profile and bore cutting; mastering clamp plate fixturing, edge-finding XY error correction, and path simulation verification workflow"}]}],"github":"","images":[{"src":"/images/swerve/swerve-cad-iso.jpg","caption":"Gen 3 Swerve Drive — 3D CAD isometric view"},{"src":"/images/swerve/swerve-cad-4view.jpg","caption":"Gen 3 Swerve Drive — 4-view engineering drawing"},{"src":"/images/swerve/swerve-assembled-top.jpg","caption":"Assembled — top view (gear transmission system visible)"},{"src":"/images/swerve/swerve-assembled-side.jpg","caption":"Assembled — side view (motors and chassis structure)"},{"src":"/images/swerve/swerve-gears-internal.jpg","caption":"Internal gear set (3D printed gears + metal parts)"},{"src":"/images/swerve/swerve-bevel-gear.jpg","caption":"Bevel gear and drive motor CAD model"},{"src":"/images/swerve/swerve-plate-cnc.jpg","caption":"CNC-machined aluminum plate"},{"src":"/images/swerve/swerve-gear-drill.jpg","caption":"Metal bevel gear drilling"},{"src":"/images/swerve/swerve-wire-cut-action.jpg","caption":"Wire EDM cutting gear bore (in progress)"},{"src":"/images/swerve/swerve-wire-cut-panel.jpg","caption":"Wire EDM control panel — hexagonal path simulation"},{"src":"/images/swerve/swerve-flowchart-algo.png","caption":"LabVIEW vector-composition kinematics algorithm flowchart"},{"src":"/images/swerve/swerve-wiring.png","caption":"FRC robot electrical system wiring diagram"}]}}', updated_at=datetime('now') WHERE id='swerve';

UPDATE projects SET zh='{"id":"nkhs-tree-map","cover":"/images/nkhs-tree-map/cover.png","category":"大學校外作品","title":"教師委託：校園樹木量測系統","period":"2026","description":"我負責整理學生與教師操作流程、角色權限、系統架構及驗收交接；AI 協助程式與測試實作。系統含 QR 量測、教師管理與地圖檢視，已有自動化測試、GitHub Actions CI 和交接文件，目前由教師測試使用，尚未正式採用。","tags":["PWA","JavaScript","Google Apps Script","Google Sheets","QR Code"],"detail":{"purpose":"受教師委託整理校園樹木量測流程，讓學生現場登錄，教師管理名單、檢視資料並接手維護。","concept":"我負責需求訪談、學生／教師流程、角色權限、架構選擇及驗收條件。學生掃描樹牌 QR Code 登錄量測；教師端管理資料並查看地圖。AI 協助程式與測試實作，我檢查流程是否符合需求。","outcome":"已加入自動化測試、GitHub Actions CI 與交接文件。目前教師正在測試使用，尚未正式採用；這是教師委託原型，不宣稱已成為校方正式系統。","tech":[{"group":"手機網頁","items":[{"name":"可安裝 PWA","desc":"以手機瀏覽器開啟量測流程，可加入主畫面；前端部署位置以目前專案設定為準。"},{"name":"QRCode 掃描流程","desc":"從樹牌進入對應紀錄頁，學生填寫量測角度、距離與樹圍。"}]},{"group":"資料流程","items":[{"name":"樹高計算","desc":"依眼高、仰角與距離計算樹高，前端與 Apps Script 使用一致的計算規則。"},{"name":"Google Sheets 儲存","desc":"Apps Script 接收量測紀錄並寫入試算表，教師端可匯出或管理資料。"}]},{"group":"教師工具","items":[{"name":"樹木地圖","desc":"在地圖上依量測高度著色；尚未量測的樹木另有標示。"},{"name":"名單與 QR 標籤","desc":"教師管理名單、角色權限與樹牌 QR 標籤；相關頁面目前由教師測試，尚未正式採用。"}]}],"github":"https://github.com/Jcsk7049/nkhs-tree-map","demo":"https://jcsk7049.github.io/nkhs-tree-map/public/app.html","images":[{"src":"/images/nkhs-tree-map/cover.png","caption":"GitHub Pages 正式版入口畫面；教師地圖和管理頁需要教師 Google 帳號。"}]}}', en='{"id":"nkhs-tree-map","cover":"/images/nkhs-tree-map/cover.png","category":"大學校外作品","title":"Teacher-Commissioned Campus Tree Measurement System","period":"2026","description":"I defined student and teacher workflows, role permissions, system architecture, acceptance, and handover; AI assisted with implementation and tests. The system includes QR measurement, teacher management, and map views, with automated tests, GitHub Actions CI, and handover docs. Teachers are testing it; it has not been formally adopted.","tags":["PWA","JavaScript","Google Apps Script","Google Sheets","QR Code"],"detail":{"purpose":"At a teacher’s request, I organized the campus tree measurement workflow so students can record readings in the field and teachers can manage rosters, review data, and take over maintenance.","concept":"I handled requirements, student/teacher workflows, role permissions, architecture, and acceptance criteria. Students scan a tree-tag QR code to submit measurements; teachers manage records and view a map. AI assisted with implementation and tests, which I checked against the intended workflow.","outcome":"The project includes automated tests, GitHub Actions CI, and handover documentation. Teachers are currently testing it; it has not been formally adopted and is not presented as an official school system.","tech":[{"group":"Mobile Web","items":[{"name":"Installable PWA","desc":"The measurement flow opens in a mobile browser and can be added to the home screen; deployment is described according to the current project configuration."},{"name":"QR Measurement Flow","desc":"Scan a tree tag to open its record, then enter measurement angle, distance, and circumference."}]},{"group":"Data Flow","items":[{"name":"Tree-Height Calculation","desc":"Calculate height from eye level, angle, and distance using matching frontend and Apps Script rules."},{"name":"Google Sheets Storage","desc":"Apps Script receives measurements and writes them to a spreadsheet for teacher review and export."}]},{"group":"Teacher Tools","items":[{"name":"Tree Map","desc":"Color map markers by measured height and distinguish trees without a reading."},{"name":"Roster and QR Labels","desc":"Teacher tools manage rosters, role permissions, and tree-tag QR labels; teachers are testing these pages, and the system has not been formally adopted."}]}],"github":"https://github.com/Jcsk7049/nkhs-tree-map","demo":"https://jcsk7049.github.io/nkhs-tree-map/public/app.html","images":[{"src":"/images/nkhs-tree-map/cover.png","caption":"Live GitHub Pages entry screen. The teacher map and management pages require a teacher Google account."}]}}', updated_at=datetime('now') WHERE id='nkhs-tree-map';

UPDATE projects SET zh='{"id":"analog-ic-studio","category":"大學校外作品","title":"Analog IC Studio — 類比 IC 自動調參平台","period":"2026","description":"用 Python、Ngspice 與 SciPy 做類比電路模擬和元件尺寸搜尋，包含運算放大器、Bandgap、振盪器與 VCO。這是模擬工具；目前線上展示站無法啟動。","tags":["Python","Ngspice","sky130 PDK","SciPy","Flask"],"detail":{"purpose":"我把類比電路的模擬與調參流程整理成工具，讓使用者輸入目標後，可以比較不同元件尺寸下的模擬結果。","concept":"工具以 Ngspice 執行電路模擬，再由 SciPy 搜尋元件參數。涵蓋 AC、DC 與瞬態分析；sky130 模式使用公開 PDK。輸出是模擬結果，並非晶片實測數據。","outcome":"目前完成多種電路拓樸的模擬與參數搜尋程式。線上 Space 暫時無法使用，因此這裡不提供可操作的即時展示。","tech":[{"group":"模擬引擎","items":[{"name":"Ngspice 閉環模擬","desc":"AC/DC/瞬態自動萃取 Gain/PM/UGF、溫漂、振盪頻率；自我修復護欄偵測不收斂自動重試"},{"name":"sky130 真實 PDK","desc":"接 SkyWater sky130 開源製程（BSIM4），含 tt/ff/ss 角落，與 Level-1 快速模型雙模對照"}]},{"group":"最佳化演算法","items":[{"name":"多變量混合優化","desc":"每顆 MOS 獨立 W/L（最多 14 維），SciPy DE 全域 + Nelder-Mead 局部，多線程平行評估"},{"name":"物理護欄","desc":"強制 Wp=2~3×Wn（遷移率比）杜絕非物理解；Pelgrom 失配良率模型 σ∝1/√WL"}]},{"group":"RFIC 分析與部署","items":[{"name":"RFIC 看盤","desc":"相位雜訊（Leeson）、FTR 調諧曲線、Kvco、PVT 27 角落、帕雷托套餐、佈局 finger 拆分"},{"name":"雲端部署","desc":"線上展示目前無法啟動；此頁只描述本機原型，不宣稱已部署服務。"}]}],"github":"https://github.com/Jcsk7049/analog-ic-studio","demo":null,"images":[{"src":"/images/analog-ic-studio/cover.png","caption":"本機 Flask 儀表板實際畫面；此次擷取只開啟介面，未執行電路最佳化。"}]},"cover":"/images/analog-ic-studio/cover.png"}', en='{"id":"analog-ic-studio","category":"大學校外作品","title":"Analog IC Studio — Automated Analog IC Tuning Platform","period":"2026","description":"A Python, Ngspice, and SciPy toolkit for simulating analog circuits and searching component sizes, including op amps, bandgap references, oscillators, and VCOs. It is a simulation tool; the hosted demo is currently unavailable.","tags":["Python","Ngspice","sky130 PDK","SciPy","Flask"],"detail":{"purpose":"I organized analog simulation and tuning into a tool where users can set a target and compare simulated results for different component sizes.","concept":"Ngspice runs circuit simulations and SciPy searches component parameters. The project covers AC, DC, and transient analysis; sky130 mode uses the open PDK. Results are simulations, not silicon measurements.","outcome":"The project includes simulation and parameter-search code for several circuit topologies. The hosted Space is currently unavailable, so there is no live demo.","tech":[{"group":"Simulation Engine","items":[{"name":"Ngspice closed-loop","desc":"AC/DC/transient auto-extract Gain/PM/UGF, drift, frequency; self-healing guard retries on non-convergence"},{"name":"Real sky130 PDK","desc":"SkyWater sky130 open process (BSIM4) with tt/ff/ss corners, paired with a fast Level-1 model"}]},{"group":"Optimization","items":[{"name":"Multi-variable hybrid","desc":"Per-instance W/L (up to 14-D), SciPy DE global + Nelder-Mead local, parallel multi-threaded eval"},{"name":"Physics guard","desc":"Enforces Wp=2-3x Wn (mobility ratio); Pelgrom mismatch yield model, sigma ~ 1/sqrt(WL)"}]},{"group":"RFIC & Deployment","items":[{"name":"RFIC dashboard","desc":"Phase noise (Leeson), FTR tuning curve, Kvco, 27-corner PVT, Pareto packages, finger splitting"},{"name":"Cloud deploy","desc":"The public demo is currently unavailable, so this page describes the local prototype without claiming a hosted deployment."}]}],"github":"https://github.com/Jcsk7049/analog-ic-studio","demo":null,"images":[{"src":"/images/analog-ic-studio/cover.png","caption":"Actual local Flask dashboard; the interface was opened for this capture, without running circuit optimization."}]},"cover":"/images/analog-ic-studio/cover.png"}', updated_at=datetime('now') WHERE id='analog-ic-studio';

INSERT INTO projects (id,zh,en,sort_order) SELECT 'cross-project-agent','{"id":"cross-project-agent","category":"大學校外作品","title":"跨專案 AI Agent 原型","period":"2026","description":"我提出需求與架構，串接 LLM API，讓不同專案共用紀錄與決策脈絡；AI 協助程式實作。目前僅個人測試使用。","tags":["LLM API","AI 協作開發","共享紀錄","需求與架構"],"detail":{"purpose":"跨專案工作時，希望保留已確認的紀錄與決策脈絡，減少每次重述需求。","concept":"我整理需求與架構，串接 LLM API 和共用紀錄流程；AI 協助程式實作。我負責檢查資料流及輸出是否符合預期。","outcome":"目前為個人測試中的原型，尚無企業部署或正式使用案例。","tech":[{"group":"需求與整合","items":[{"name":"需求與架構規劃","desc":"由我整理使用情境、共用資料與決策脈絡的需求。"},{"name":"LLM API 串接","desc":"串接 LLM API，依專案上下文提供共用紀錄；目前僅個人測試。"},{"name":"AI 協作實作與檢查","desc":"AI 協助程式實作，我負責需求檢查與個人環境測試。"}]}],"github":"","images":[]}}','{"id":"cross-project-agent","category":"大學校外作品","title":"Cross-Project AI Agent Prototype","period":"2026","description":"I defined the requirements and architecture and connected an LLM API so multiple projects can share records and decision context. AI assisted with implementation. It is currently for personal testing only.","tags":["LLM API","AI-assisted development","Shared records","Requirements & architecture"],"detail":{"purpose":"I wanted to preserve confirmed records and decisions across projects instead of restating requirements each time.","concept":"I defined requirements and architecture and connected an LLM API with shared records. AI assisted with implementation; I checked data flow and outputs against expectations.","outcome":"This is a prototype in personal testing, with no enterprise deployment or formal usage case.","tech":[{"group":"Requirements & Integration","items":[{"name":"Requirements and Architecture","desc":"I documented the use cases and requirements for shared data and decision context."},{"name":"LLM API Integration","desc":"Connected an LLM API to provide shared records in project context; currently for personal testing only."},{"name":"AI-Assisted Implementation and Review","desc":"AI assisted implementation; I checked requirements and tested in my own environment."}]}],"github":"","images":[]}}',99 WHERE NOT EXISTS (SELECT 1 FROM projects WHERE id='cross-project-agent');
